-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[57131] = { id = 57131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Hunt Begin", description = "One step remains until we may begin the Penitent Hunt.\n\nYou and the other hunters will first siphon a small amount of anima from the souls. It will come with ease. The soul's time in the Grove of Terror causes trace anima to release.\n\nThis anima helps us venthyr in tracking the prey's fear.\n\nI also ask that you do us the honor of signaling the hunt.\n\n<The Fearstalker hands you an anima stake and a hollowed dredbat fang.>\n\nUse these to complete the task.", progress = "The ceremony must continue.", completion = "Well done. Perhaps in death you will make a fine hunter.\n\nI can practically taste the fear we will inflict.", objectives = "Complete the hunting ritual at Wanecrypt Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57136] = { id = 57136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Penitent Hunt", description = "You will descend upon these poor souls. Remember, you are helping them and Revendreth through the terror you bring. When a soul is filled with fear, their resistances to our methods falter.\n\nThe Master has requested that you hunt the Accuser yourself. But we must prey upon some of the others first.\n\nI will be able to guide you through your first hunt.", progress = "The souls must be hunted.", completion = "Well done. The fear we struck allowed us to extract ample anima for Revendreth.\n\nOnto our final target.", objectives = "Speak to the Fearstalker in Wanecrypt Hill and participate in the Penitent Hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57146] = { id = 57146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption Tear" }
quests[57147] = { id = 57147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not My Warchief", description = "There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision.\n\nWe must make our way to the wyverns and take to the skies.", completion = "Eitrigg told me of your escape from Orgrimmar. There may still be other dissenters within the city who are unable to leave such as you did.\n\nAll we can do for them now is end this battle before Sylvanas makes them suffer.", objectives = "Escape with Eitrigg and meet up with Saurfang in Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57148] = { id = 57148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegebreakers", description = "The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates.\n\nOur operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half.\n\nYour task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.", completion = "I weep for them. The fools.\n\n<Nathanos smirks.>", objectives = "Covertly place Suspicious Crates and slay guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57149] = { id = 57149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda Takedown", description = "Recently, dissidents have been posting propaganda around the city and spreading all manner of lies.\n\nThis is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers.\n\n<Nathanos rolls his eyes.>\n\nTear down the rubbish. It can only lead to panic in the streets. \n\nAnd should you encounter any... resistance... you are hereby authorized to respond with force.", completion = "Well done. I expect you faced little resistance of note.", objectives = "Burn Dissident Propaganda in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57150] = { id = 57150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Militia", description = "The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield.\n\nRally the citizens and form a militia! Remind them of their slain brothers and sisters!", completion = "Our armies swell while those of our enemies wither away.", objectives = "Rally the citizens of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57151] = { id = 57151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line in the Sand", description = "Now that we have put our house in order, it is time to purge the filth before our gates.\n\nHow thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop.\n\nLet us end this pitiful rebellion.", completion = "I have orders for you from the Dark Lady. She instructed me to deliver them on her behalf, should things play out this way.", objectives = "Speak with Nathanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57152] = { id = 57152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Most Loyal", description = "The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly.\n\nYou are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. \n\nShe will meet you near Windrunner Spire.", completion = "You will be remembered for your loyal service.", objectives = "Speak with Sylvanas Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57153] = { id = 57153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven District" }
quests[57155] = { id = 57155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Eye", description = "Ah yes, just the {class} I wanted to see.\n\nI can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection.\n\nThrough my research I have learned a less painful way of removing the infection.\n\nSpeak with me, and let's put an end to this nightmare.", sourceObjective = "Speak with Brother Pike to cleanse your \"gift\".", sourceObjectiveStatus = "unverified-source-field" }
quests[57156] = { id = 57156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Eye", description = "You finally arrived {name}. Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you.\n\nDis won't hurt. Much.\n\nTell me when you are ready to begin.", sourceObjective = "Speak with Nailok to cleanse your \"gift\".", sourceObjectiveStatus = "unverified-source-field" }
quests[57157] = { id = 57157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: The Black Empire", description = "It is just as the visions fortold. Dark forces have come to claim the Forge of Origination.\n\nThey must be stopped, or all of Azeroth will meet its end!", progress = "The madness... it consumes!", completion = "The voices have stopped. The visions show me the dawn.\n\nWe will survive this day, thanks to you.", objectives = "Drive back the N'Zoth Assault in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57158] = { id = 57158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Electric Empowerment" }
quests[57159] = { id = 57159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Reflection of Truth", description = "I sent the Fearstalker far from here with that trap--buying us some time.\n\nOn the other side of this mirror lies the depths of Castle Nathria, the fortress of Denathrius himself. There, a meeting between Denathrius and one of his lackeys is about to take place.\n\nJoin me through the mirror, {name}. You shall see the truth of this \"drought\" first hand.", completion = "We barely made it. Denathrius will surely be on our trail soon.", objectives = "Follow the Accuser through the mirror and witness the truth of Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57161] = { id = 57161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Don't Get My Hands Dirty", description = "You heard Sire Denathrius. Today, I ascend to the Court of Harvesters.\n\nYou are fortunate to have the honor of witnessing my rise to power.\n\nThe traitors have barricaded the bridge ahead. Clear a path for me, so that I might cross it undisturbed.\n\nNothing can stand against me now that I have a Harvester's medallion.\n\nBut I will not waste my power on this rabble.", progress = "Clear the way for Lord Chamberlain!", completion = "<Echelon grunts.> You're late.", objectives = "Clear the bridge for Lord Chamberlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57164] = { id = 57164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devour This", description = "Though the souls are our primary target, another challenge has arisen.\n\nThe Banewood has seen an infestation of devourers: disgusting vermin who gorge themselves on the anima we need to survive. A fitting challenge for any true hunter, no?\n\nI should only thank the Master that they have remained in a few secluded pockets. I loathe to think that their numbers could multiply. Let us exterminate them before they pose a true threat.", progress = "Are the devourers finished?", completion = "Once you master fear, all crumble before you.", objectives = "Eliminate the devourers in the Banewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57165] = { id = 57165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[57167] = { id = 57167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[57171] = { id = 57171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbough Guardian" }
quests[57173] = { id = 57173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accuser's Sinstone", description = "Lord Chamberlain will cross the bridge when it pleases him.\n\nBefore he arrives, you will seize the Accuser's sinstone.\n\nWise venthyr like Lord Chamberlain hide their sinstone, so that it can never be used against them.\n\nThe Accuser is too proud to hide her sinstone. Instead, she puts it on display for all to see.\n\nBoasting of the many, many sins she's overcome.\n\nProud. Arrogant. Most importantly, foolish.\n\nHer sinstone lies on the altar before us, seemingly unguarded. Retrieve it.", completion = "Is that truly the best you have to offer?", objectives = "Investigate the Accuser's sinstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57174] = { id = 57174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stoneborn", description = "The Stone Legion is not even here yet? This is an outrage.\n\nIf we do not do something quickly, the rebels will overrun this filthy hamlet.\n\nHere, take the anima and go activate a few of the stoneborn along the periphery of Darkhaven. Take whatever is left over to the Quartermaster and tell her to do her job.\n\nI will try to commune with the Master and see if he can send reinforcements.", progress = "Darkhaven. Such a pitiful hamlet filled with unworthy supplicants.", completion = "This is all that remains of our tithe? The Tithelord is not one for excuses. We may need to gather a second tithe quickly or he will condemn us all to the Ember Ward.", objectives = "Collect the Anima Cage and then awaken 6 Stoneborn Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57175] = { id = 57175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Vilhelm's Sinstone", description = "Inquisitor Vilhelm has taken exceptional precautions to protect his sinstone.\n\nBroken into several pieces and hidden from sight, he believed his sinstone would be safe from us.\n\nBut his plan had the same weakness as most: he trusted weak-willed underlings.\n\nI \"interrogated\" several dredgers to learn where they helped the inquisitor hide the broken fragments of his sinstone.\n\nFind all the fragments and bring them to me.", completion = "<As Echelon holds the sinstone fragments, anima binds draw the pieces into one another, reforming into a completed sinstone.>\n\nWe are ready to proceed.", objectives = "Collect the 3 Hidden Sinstone Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57176] = { id = 57176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinstone Delivery", description = "Lord Chamberlain has held off the Accuser to buy us the time we needed to break the ward on her sinstone.\n\nBut, thanks to your delays, our reinforcement of his position is overdue.\n\nI will collect the Accuser's sinstone and carry us to the battle.", completion = "This is, in fact, one of the larger sinstones I have seen.\n\nThis will be easy to exploit.", objectives = "Fly with Echelon and deliver the Accuser's Sinstone to Lord Chamberlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57177] = { id = 57177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fresh Start" }
quests[57178] = { id = 57178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Awaits", description = "Maw Walker, I am General Kaal. Those stoneborn who remember their oaths to the Master are under my command.\n\nThe path between here and Sire Denathrius is no longer secured by my forces. I am pulling my troops from this ward to support the Master's will elsewhere. \n\nSire Denathrius has dispatched me to bring you directly to him. Myskia can carry you.", progress = "Mind your manners when speaking to Sire Denathrius. He is a being older than your world.", completion = "Wait! Please, Maw Walker, allow me to announce you to the Master.", objectives = "Meet Sire Denathrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57179] = { id = 57179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Authority of Revendreth", progress = "My eyes are everywhere.", completion = "Now, Maw Walker, arise as a weapon of ordained power within my dominion.", objectives = "Accept the Master's Boon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57180] = { id = 57180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accuser's Secret", description = "Now that I possess the Accuser's sinstone, I can finally end her treasonous charade once and for all!\n\nProtect me while I study this sinstone, and you will be rewarded as first among my retainers.\n\nAfter I crush her with my incredible power, I will seize control of the Halls of Atonement and receive the Master's reward.\n\nThis feat heralds my own ascension to the Court of Harvesters!", completion = "<Lord Chamberlain smiles wryly.>\n\nThe Halls of Atonement are under my control.", objectives = "Help Lord Chamberlain defeat the Accuser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57182] = { id = 57182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accuser's Fate", description = "You now stand in the presence of a Harvester, Maw Walker.\n\n<Lord Chamberlain breathes in deeply and smiles.>\n\nI will use the Accuser's medallion to solidify my foothold over the Halls of Atonement.\n\nMeanwhile, the Master has requested that you deliver both the Accuser and the medallion that he loaned to me.\n\nMyskia will be along shortly to retrieve you. Do not keep the Master waiting.", progress = "I trust you have the medallion that I loaned to the Lord Chamberlain?", completion = "<Sire Denathrius smiles as you hand him the medallion.>\n\nI am pleased to see that you can be trusted with great power.", objectives = "Ride Myskia and deliver the Accuser to Sire Denathrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57185] = { id = 57185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dutybound", description = "Welcome to the fight, {name}. You're with us now.\n\nTake a moment and introduce yourself. I will meet you by Draven at the lodge.", objectives = "Introduce yourself to General Draven, Nadjia the Mistblade, and Rendle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57189] = { id = 57189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Hopebreakers", description = "The Fearstalker has surely sent her hunters across the entirety of the Banewood in search of us, {name}. \n\nDraven informed me that some of her top hunters are scouring Dredhollow as we speak. We can use this to our advantage. Slaying them should get her attention.\n\n<The Accuser hands you a collection of bright red vials.>\n\nThrow these on her hunters. It should draw the attention of the devourers infesting this place.", completion = "Sounds like it worked better than expected. \n\nPerfect. The Fearstalker stands no chance.", objectives = "Use the Concentrated Anima Vial to defeat the hopebreakers in Dredhollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57190] = { id = 57190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Won't Know What Hit Them", description = "Luring the Fearstalker here will prove pointless unless we can tilt the odds. She will surely show up with a small army. \n\nPlant these anima containers. When the time comes, we will release their contents into the air, dousing her and her forces in a thick layer of anima.\n\nThat should get the devourers infesting this place to flock to them like moths to a flame.", completion = "The devourers will rip them to shreds.", objectives = "Plant 8 Rigged Anima Containers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57198] = { id = 57198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sense of Obligation", description = "Derek is free. I have to atone for much with him.\n\nThere is a rumor of a meeting with Jaina and her brother.\n\nHead to Seabreeze Village in Stormsong Valley. I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus.\n\nIf you find out anything of interest, I would be most appreciative.\n\nFor now, let's keep this between the two of us.", completion = "Well, that is interesting...\n\nI must act quickly.", objectives = "Eavesdrop on Jaina Proudmoore's meeting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57205] = { id = 57205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Bumps Along the Way", description = "This territory is strategic to our defense, we can not allow these abominations to force our retreat!\n\nSeize control of two of the locations marked on your map. Defend them from enemy attack till the flag is planted and the location captured.", objectives = "Defend and capture two locations", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57207] = { id = 57207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lysonia's Plan", description = "Lysonia has brought the Paragon to his knees! The Maw powers she wields are far too potent.\n\nWe must stop her.", progress = "<The Paragon of Humility clutches his body in pain.>", completion = "I am weakened, but I will heal.\n\nShe searched for pride that does not exist within me.", objectives = "Confront Lysonia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57215] = { id = 57215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engine of Ascension" }
quests[57217] = { id = 57217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Keeper" }
quests[57218] = { id = 57218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Keeper" }
quests[57219] = { id = 57219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Keeper" }
quests[57220] = { id = 57220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Protocol Initiation", description = "We've come a long way, {name}.\n\nOnce the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics.\n\nAll that's left is settin' the final pieces in place.", progress = "Quite the journey so far.", completion = "Best get tae it 'fore things get out of hand.", objectives = "Relay power from the Chamber of Heart, Engine of Nalak'sha and Forge of Origination auxiliary systems, then speak with MOTHER to power up the Forge of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57221] = { id = 57221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Origination", description = "If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination.\n\nWe best get back tae investigate, {name}.", completion = "We won't be findin' any answers out here.", objectives = "Meet Magni Bronzebeard outside the Halls of Origination in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57222] = { id = 57222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Halls", description = "Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers.\n\nBest check yer gear 'fore headin' in, {name}. Who knows what's waitin' fer us in there.", completion = "If N'Zoth were to gain access to the forge and leverage its power the results would be... catastrophic.\n\nI'm afraid we're short on time, {name}. If you're going to continue these investigations, you'll need protection.\n\nAnd I know just the place.", objectives = "Investigate the anomaly in the Halls of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57223] = { id = 57223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Keeper" }
quests[57225] = { id = 57225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[57226] = { id = 57226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[57228] = { id = 57228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault on Dredhollow", description = "The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us.\n\nWe have done all we can do to prepare for their assault. Here.\n\n<The Accuser gives you an ornate staff.>\n\nI fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces.\n\nThe fight begins.", objectives = "Defeat 12 of the Fearstalker's Forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57234] = { id = 57234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solar Collector" }
quests[57235] = { id = 57235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solar Collector" }
quests[57240] = { id = 57240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where is Prince Renathal?", completion = "You no go here. Here for bad buds!", objectives = "Speak with Stonehead, gatekeeper of the Ember Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57243] = { id = 57243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amathet Slave Camp" }
quests[57245] = { id = 57245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ani-Matter Animator", description = "This area is rich with the remains of fallen soldiers... some of which still carry a spark of potential.\n\nI've created what I call the \"Ani-Matter Orb,\" with which you can reanimate the skeletal matter littered throughout the foundry. \n\nLet us see how many of the new animates would join our cause.\n\nAs for those who don't... well, they should be quite accustomed to being slain by now.", progress = "Do we have enough animates?", completion = "These reanimated troops will be put to good use.", objectives = "Recruit 15 animates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57246] = { id = 57246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eel Filet", progress = "Yes? What is it?", completion = "My favorite! How did you know?\n\nI will cook it up for the camp, everyone is going to enjoy this." }
quests[57247] = { id = 57247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathom Ray Wing", progress = "Yes? What is it?", completion = "That is a nice, juicy wing you have there. \n\nI will cook this up, there's plenty to go around." }
quests[57248] = { id = 57248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giant Crab Leg", progress = "Yes? What is it?", completion = "Wow, that is a large one. Looks delicious!\n\nI'll make some soup for tonight, the group is going to love it." }
quests[57249] = { id = 57249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timely Invitation", description = "The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. \n\nTo commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! \n\nCome to the Caverns of Time and present this ticket to gain entry to the party!", completion = "Welcome! It's that special time of year when the bronze dragonflight celebrates all that has happened over the years and you, {name}, are the guest of honor!\nCome celebrate at the grand feast, get down at the \"Disco of Time\", or accept a quest to fend off some of Azeroth's greatest threats.", objectives = "Bring the Invitation from the Timewalkers to Chromie within the Caverns of Time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57251] = { id = 57251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57252] = { id = 57252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57253] = { id = 57253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57254] = { id = 57254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57255] = { id = 57255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57256] = { id = 57256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormchosen Arena" }
quests[57261] = { id = 57261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk the Path, Aspirant", description = "If you wish to stand before the Archon, there is a path you must walk. Thankfully, it is well worn and serviceable even in these dire times.\n\nThough you are not destined to become kyrian, our ways may be of interest to you. Learn well, learn fast, and perhaps the Archon will take notice and grant you this audience you seek.\n\nAspirant Kleia will show you the way. Archon's eyes upon you.", completion = "Your journey is just beginning, {name}. I hope you can help us, and I hope we can help you.", objectives = "Travel with Kleia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57263] = { id = 57263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of Anima: Etherwyrms", description = "Forge is cold, yes? Need LOTS of anima to light.\n\n<Sika references her scroll.>\n\nTimes before now, anima is everywhere, yes? Now it hides. Small bits, weird places.\n\nWe know that etherwyrms -- flappy scale-things that are blue -- eat anima. They are not dead, so they are finding anima to eat still, yes?\n\nMaybe if we take what they have eaten, we can use it to light the forge. This will probably kill them.\n\nSad, yes. But! We will not take too much. Just a little.", progress = "Did you find anima? Small pieces, even?", completion = "<Sika pokes the squishy substance.>\n\nIt glows. This means anima. Forgelite will be pleased.", objectives = "Slay Etherwyrms to collect 25 Glowing Viscera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57264] = { id = 57264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Edge of a Revelation", description = "Ah! Good. You answered the call.\n\nAs you can see, there are many aspirants who require our aid. Myself and the other disciples are hard pressed to deal with all of them. Some are in greater need than others.\n\nAspirants are most at risk when they are on the precipice of a revelation. It is a critical moment that we cannot allow to pass without intervention.\n\nYou must push them, one way or another.\n\nFind the most vulnerable among your peers and do what you can to help them find the path forward.", progress = "My disciples will be grateful for your aid, {name}.", completion = "Your service is noted. Thank you.", objectives = "Inspire 11 Vulnerable Aspirants to action.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57265] = { id = 57265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of Anima: Drought Conditions", description = "In days past, keeping a forge burning was a trivial task. The anima extractors could run constantly without ever running dry.\n\nNow, even turning an extractor on is a risk. Etherwyrms, without the anima streams to feed on, are attracted to any source of anima. They are a frequent nuisance.\n\nI am going to ask that you risk their attentions. Activate the extractor and guard it until it can accumulate what little anima remains.\n\nBring me the product it collects. Let us hope it is enough.", progress = "Is the extractor functional? How much were you able to acquire?", completion = "That is... somehow more and less than I expected. It will have to do.", objectives = "Collect a Condensed Anima Mote from the Anima Extractor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57266] = { id = 57266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Cleansing", description = "This situation may feel familiar, {name}.\n\nWhen you found Pelagos, he was undergoing a similar rite. As you saw, it can end in violence.\n\nThis will be the first time you are asked to draw out the burdens that held you to a mortal life. It may be a painful process. It is for many.\n\nFor you, this is the path you must walk to attain your goals. To earn the right to stand among us, to be heard. So we may carry your message to the Archon herself.\n\nCenter yourself. When you are prepared, we will begin.", completion = "This is a moment worthy of celebration, {name}.\n\n\n\nYou have done it. They have come.", objectives = "Undergo your first cleansing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57267] = { id = 57267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of Anima: Flower Power", description = "For forge to light, need more anima. Always more. Never too much, for forge!\n\n<Sika consults her scroll and nods vigorously as she reads.>\n\nOut in fields, there is a glowy flower. The round thing inside. Bulb? It glows. So, has anima. From the ground, we think.\n\nAccording to scrolls, it is called Adrima's Lily. We do not know who Adrima is. But the lily is good.\n\nGet flowers, too. Not just bulbs. Petals make stewards happy, too. \n\nThank you!", progress = "Do you have flower bulb things?", completion = "Oh. They smell nice! And they glow lots.\n\nThis is good. Yes.", objectives = "Collect 6 Adrima's Lily.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57269] = { id = 57269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Doubt", description = "Quickly! We have no time to lose. Lysonia has weakened Eridia to the point that she may fall. Our Paragon will do what she can, but we must intervene.\n\nWe will challenge Lysonia, and perhaps buy Eridia more time. \n\nThis so-called Hand of Doubt will make no easy foe. Stand ready, {name}.", completion = "That you should join us now, on the precipice of this treachery, is curious.\n\n<The Paragon of Purity studies you with a piercing gaze.>\n\nYou have done well. The Archon will know of your contributions this day.", objectives = "Defeat Lysonia, Hand of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57270] = { id = 57270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Purity", description = "Greetings.\n\nI am Kosmas, Disciple to the Temple of Purity.\n\nThe temple is a place of cleansing. Its sole purpose is to free aspirants of the burdens they carry with them from life. It is a place of quiet reflection even for those who have shed their burdens.\n\nOf late, those who look to us for purification have grown numerous. My fellow disciples are stretched terribly thin. I have come to ask the aid of all able-minded aspirants.\n\nYour help is needed. Please report to the Hand of Purity at once.", completion = "Thank you for volunteering.", objectives = "Meet the Hand of Purity at the Temple of Purity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57271] = { id = 57271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trade District" }
quests[57272] = { id = 57272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodbound Effigy" }
quests[57274] = { id = 57274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quartermaster's Bounty", progress = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", completion = "Victory at any cost." }
quests[57275] = { id = 57275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something in Your Mind", description = "<Looking into the crystal, the light around you is slowly drowned in inky smoke. An imposing presence crushes down on you, whispering unintelligibly in your ear. Looking for the source, you see nothing, but the sensation grows. Your head begins to swim as the darkness deepens and the noise becomes deafening.\n\nSummoning all your willpower to steel your resolve...\n\nThe light has returned, the noise silenced, and you stand with a humble crystal in your hand.\n\nPerhaps Wrathion knows more about it...>", completion = "<Wrathion's brow furrows when he sees the crystal.>\n\nIt is fortunate you brought this to me. Impressive that you were able to handle it while retaining your sanity. In fact... this may provide us with an opportunity.\n\n<Wrathion strokes his chin, lost in thought.>\n\nI will not mince words, {name}. This will certainly prove dangerous. However, I have full confidence that you are up to the task. Now, let us wield N'Zoth's own power against him.", objectives = "Bring the Void Focus to Wrathion in the Chamber of Heart.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57276] = { id = 57276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", progress = "We are embarking upon a dangerous gambit, {name}. Caution is of the utmost importance.", completion = "Excellent. These should provide just what we need.\n\nI will draw out the corruption from these physical vessels and infuse it into the focus. Then you will be able to use it to create more powerful items.", objectives = "Acquire 20 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57277] = { id = 57277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette - Muminah the Incandescent" }
quests[57278] = { id = 57278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Their Heads", description = "I swore to the grave of Vistara the Fallen that I would bring him the head of the one who betrayed him. \n\nThough that was eons ago, it is an oath I must fulfill. Whatever fate ultimately befell the traitor, it is likely that his head can still be found nearby.\n\nSlaughter everyone here. Surely one of them must be the traitor... or be in possession of his head.", progress = "Do you have the traitor's head?", completion = "I have asked many others to collect heads as well! So even if none of these are the traitor's head, we shall find it eventually!", objectives = "Collect 10 Traitor's Heads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57282] = { id = 57282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Quarter" }
quests[57284] = { id = 57284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade of Blades", description = "The finest sword in existence has been lost!\n\nNever in your pitiful adventures have you encountered such a blade, mortal. Foe Cleaver was forged to strike down the titans themselves!\n\nI have wielded it against countless adversaries. Emissaries of the Light, minions of the Void, meddlers from the Gardens of Life... all have fallen before me! Soon the very planes of reality will kneel to my greatness!\n\nOnce I find my weapon, that is.\n\nI insist you help me reclaim it. I know it's here somewhere!", progress = "Have you found Foe Cleaver? Well? HAVE YOU?!", completion = "Foe Cleaver! Now my crusade of conquest begins!\n\nYou... you act as if you've seen finer swords, mortal. How dare you!\n\nJust you wait. You'll kneel before me just like all the rest!\n\n<The animate mutters and grunts.>", objectives = "Find Foe Cleaver amongst the forgotten weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57288] = { id = 57288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assessing Your Strength", description = "The trial to come will test you in ways you can likely only imagine.\n\nI can see both from your past and from your demeanor that you are no stranger to combat. I would like to know where your strengths lie so we may address any weaknesses we find before your trial.\n\nYou will find three praetorian soldiers created for this purpose, each stronger than the last.\n\nDefeat them all and I will consider your strength sufficient to continue at this time.", progress = "How fares the combat?", completion = "Impressive. I see I have little enough to teach you.", objectives = "Defeat the 3 Praetorian Sparring Assistants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57290] = { id = 57290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning the Descent", description = "Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent.\n\nUntil recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge.\n\nIf we are to find answers, there is one place to look.\n\nOur journey continues, {name}. Blackrock awaits.", progress = "Have you recovered what we discussed?", completion = "The scales of corruption now serve as protection for those who stand against it.\n\nHow fitting.\n\nNow, let's see what a {class} of your caliber is capable of when dressed for the occasion.", objectives = "Retrieve the Corrupt Black Dragonscale from Blackwing Descent atop Blackrock Mountain in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57291] = { id = 57291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of First Reflection", description = "Ah, Athanos. It remains undefeated, as intended.\n\nStill, you have exceeded any expectation I might have had. You are stronger than many that have come before you.\n\nYou have come here for a purpose, and Kleia has illuminated a path that she believes you can walk. I agree. I have opened the way to the Crucible's final rite.\n\nFollow the path to the south and east. There you will find the entrance to the Chamber of First Reflection.\n\nKleia will instruct you further. Go in service, {name}.", completion = "Gather yourself. This is how you will find your way before the Archon. I am certain of it.", objectives = "Speak to Kleia in the Chamber of First Reflection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57298] = { id = 57298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Things \"Really\" Happened...", description = "You've come a long way over the years, {name}.\n\nFrom humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world.\n\nBut why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! \n\nDon't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.", progress = "Hey, did we win yet? Or have we begun? I'm maybe not yet sure. Keeping the timelines straight gets a bit difficult.", completion = "Yay! Wasn't that fun? And absolutely NOTHING bad happened to you, ever!\n\n<Chromie gives you a playful wink.>", objectives = "Embark from the Caverns of Time with Chromie to defeat villains of the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57299] = { id = 57299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Sarcophagus" }
quests[57300] = { id = 57300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soldier of Time", description = "Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. \n\nWell, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.", progress = "Did you have fun exploring Alterac Valley as it used to be?", completion = "The battles for Alterac were bloody affairs, I'm glad they're done. Oh wait, the battles are still ongoing! The cycle of strife is never ending.", objectives = "Earn 500 honor in Korrak's Revenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57301] = { id = 57301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Callous Concoctions", description = "I witnessed your success with the Pool of Potions and I think you could be of help. Within this larger pool, we create more dangerous mixtures!\n\nThere are three different oozing ingredients we mix together in different combinations to create violent creatures. When enough ingredients have been added to the pool, the mixture takes shape and a creature will emerge!\n\nBring any combination of these ingredients, Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities.", progress = "Have you completed the mixture?", completion = "You may continue to add as many ingredients as you wish. The more we add, the more we create!", objectives = "Deliver any combination of Mephitic Goo, Viscous Oil, or Miscible Ooze to the Pool of Mixed Monstrosities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57302] = { id = 57302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", completion = "Well done!  Graveyards are vital to our control of Alterac Valley.  When you capture one, you help ensure the Alliance's sovereignty here.\n\nGo now, {name}.  Reenter the battle, and if you see a graveyard under the Horde's control... you know what to do!", objectives = "Assault a graveyard, then return to Sergeant Durgen Stormpike in Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57303] = { id = 57303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", completion = "It's good to see fresh troops here, {name}, but with a little luck you'll get into some action and won't be fresh for long!\n\nSpeak with me again.  I have tasks I must discuss with you....", objectives = "Speak with the Stormpike Quartermaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57304] = { id = 57304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", completion = "You did it!  Well done, {name}!\n\nWhen we control a mine and have troops stationed there, it's much easier to gather minerals and supplies from it.", objectives = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57305] = { id = 57305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", progress = "Did you bring any armor scraps, {name}?", completion = "These are some good pieces, {name}.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!", objectives = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57306] = { id = 57306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Armor Scraps", progress = "{name}, we need more armor scraps to supply our troops!", completion = "These are some good pieces, {name}.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
quests[57307] = { id = 57307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", completion = "I received a field report stating you helped secure an enemy banner.  Well done, {name}!  With their ranged troops out of position we can move the line of battle forward!", objectives = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57308] = { id = 57308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57309] = { id = 57309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begin the Attack!", progress = "My troops are supplied and ready to assault.  We just need orders from Noreg Stormpike and I'll send them into the fray!", completion = "Ah, the orders!  They say I'm to assault at will, and my will says... now!" }
quests[57310] = { id = 57310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irondeep Supplies", description = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, {name}.  Enter the mine and bring me a load of them.", progress = "Do you have the supplies, {name}?  We can never have enough!", completion = "Well done!  I'll put these supplies to good use!  Thanks, {name}!", objectives = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57311] = { id = 57311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldtooth Supplies", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, {name}.  The mine is to the distant south, deep in Horde territory.", progress = "Did you enter the Coldtooth mine in Horde territory, {name}?  Did you raid their supplies?", completion = "You got them!  Well done, {name}!  I'll go through these supplies and get them ready for our own troops!", objectives = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57312] = { id = 57312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", completion = "Well done, {name}!  With each graveyard under our control, the spirits of our enemies will wander more lost and aimless.", objectives = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57313] = { id = 57313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", completion = "Hail, {name}!  It is good to see a {class} like yourself, eager to do his part for the Horde.  Speak with me again, for I have vital tasks for you...", objectives = "Speak with the Frostwolf Quartermaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57314] = { id = 57314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", progress = "You haven't yet captured a mine, {name}!  Find one that we do not control and defeat it's leader!", completion = "You captured a mine!  With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.\n\nWell done, {name}.  The deed you have done is a great boon to our battle efforts.", objectives = "Capture a mine, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57315] = { id = 57315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", completion = "I heard of your mission's success!  That pleases me...\n\nOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!", objectives = "Capture an enemy tower or bunker, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57316] = { id = 57316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ladder", description = "Within the Theater of Pain, <brother/sister>, legends rise like cream to the top.\n\nListen to me, <brother/sister>. If you have the courage to step into that sacred arena, you're going to face the greatest threats in all of existence! The cards will be stacked against you, but only those who can work together will emerge as champions.\n\nGather your team and meet this challenge head on! Enter the Theater of Pain and defeat the opponents within! Prove that you can rise to the top!", progress = "Greetings, brother. Have you faced the madness of the arena?", completion = "Well fought, brother! You've begun your rise to the top!\n\nBut keep up with your training and stay ready. In Maldraxxus, there is always a challenger waiting to take your place.", objectives = "Defeat 3 opponents within the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57317] = { id = 57317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", progress = "How goes the hunting, {name}.  Do you have any armor scraps for me?", completion = "These will do nicely.  I'll melt them down and patch them up and you'll never know they came from those Stormpike cowards!\n\nThanks, {name}.  And let me polish up that armor of yours...", objectives = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57318] = { id = 57318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Booty!", progress = "I need more armor scraps, {name}!  Do you have any?", completion = "Thanks again, {name}.  You do the Horde proud..." }
quests[57319] = { id = 57319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in Frostwolf Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57320] = { id = 57320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Launch the Attack!", progress = "My warriors are eager to attack!  All I need are the assault orders...", completion = "It's about time!  Now we can show the Alliance their folly in coming to Alterac Valley!" }
quests[57321] = { id = 57321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldtooth Supplies", description = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, {name}!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...", progress = "Have you been to the Coldtooth mine, {name}?  Do you have the supplies I asked for?", completion = "Ah, you got  them.  Good work, {name}!  These supplies are a little musty from sitting in that dark mine for so long, but we'll make use of them nonetheless.\n\nThank you, {name}.  Your deeds are vital to the maintenance of our fighting forces.", objectives = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57322] = { id = 57322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irondeep Supplies", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, {name}.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", progress = "Did you enter the Irondeep mine, {name}?  Did you raid its supplies?", completion = "You got them!  Nicely done, {name}!  And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!", objectives = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57323] = { id = 57323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpent Binding" }
quests[57324] = { id = 57324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sail With the Tide", completion = "My death seems to have given me a new purpose.", objectives = "Meet with Calia Menethil and Derek Proudmoore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57326] = { id = 57326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prototypes for Profit", description = "<Gazlowe pulls you in close and whispers.>\n\nLookit here, {name}. I gotta keep my nose clean here in front of the prince.\n\nBut I trust you know what's gotta be done outside of town, yeah?\n\nOutside of town... where all the tech is...\n\nTech that Alliance grubs are tryin' to get their clumsy mitts on...\nwhich we could use for the Horde...\nto build big weapons...\nand scary robots...\nand other lucrative products...?\n\nI don't gotta spell this out for you, right?", progress = "This place is teemin' with tech. Betcha can find prototypes anywhere.", completion = "<Gazlowe flicks through the prototypes you brought.>\n\nSome good stuff in here, {name}... We'll get a lotta use outta these...", objectives = "Collect 150 Prototype Implants in Mechagon, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57327] = { id = 57327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prototypes for Inspiration", description = "<Overspark pulls you in close and whispers.>\n\nAs the leader of this momentous expedition, I must stay with Prince Erazmin to ensure he's not swindled by this Horde hooligan.\n\nBut I cannot stop my research, or the Horde will gain the advantage!\n\nUnderlings like yourself must collect the technology samples required to fuel my legendary brainstorms.\n\nBring me prototypes from the island, and I will turn them into groundbreaking new innovations for the Alliance!", progress = "I don't care where you get the prototypes from. Take them from Gazlowe's thugs if you have to.", completion = "<Tinkmaster flicks through the prototypes you brought.>\n\nInteresting... provocative... inspiring! I can certainly turn these into something useful.", objectives = "Collect 150 Prototype Implants in Mechagon, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57328] = { id = 57328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trashin' the Camp" }
