quests[57359] = { id = 57359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Ritual" }
quests[57362] = { id = 57362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper Into the Darkness", description = "This recent change of events allows us to continue our journey to discover what darkness lies beyond the sands.\n\nIt will not be easy, {name}. We stand on the precipice of the unknown, but now the tables have turned.\n\n<Wrathion glances at your new attire.>\n\nYou do dress the part. \n\nLet's see what insights your return to the Halls of Origination bring to light.", progress = "I await your return.", completion = "Removing the corruption from the Halls of Origination has shifted N'Zoth's attention elsewhere. The attacks on Uldum and Vale of Eternal Blossoms continue to grow.", objectives = "Speak with MOTHER to return to the Halls of Origination in Uldum to discover the source behind the anomaly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57370] = { id = 57370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: The Black Empire" }
quests[57371] = { id = 57371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: Aqir Unearthed" }
quests[57372] = { id = 57372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drag" }
quests[57373] = { id = 57373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descending Into Madness", description = "As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead.\n\nLocate one of these incursions and see what happens when you peer beyond the dark veil.", completion = "I believe it is time we put this new knowledge to good use.", objectives = "Seek out a Vision of N'Zoth amidst the corruption in Vale of Eternal Blossoms or Uldum to discover what the future holds for Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57374] = { id = 57374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Darkest Depths", description = "With our connection secured, it is time for us to breach the veil and discover what lies beyond.\n\nWhat you find may provide us the key to unlocking our success.", progress = "Your expertise in these matters are invaluable.", completion = "You've done well, but do not let what you've just seen play you for a fool. Even the safety of this chamber can create a false sense of security.\n\nThe mind is easily manipulated.", objectives = "Enter a Horrific Vision to discover what dark manifestations await in a world ruled by N'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57375] = { id = 57375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulsating Mound" }
quests[57376] = { id = 57376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Need", description = "Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. \n\nWe cannot do that without accepting ourselves. So many feel lost, alone... abandoned.\n\nI have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness.\n\nMeet me in Tirisfal Glades, at the Calston Estate.", completion = "Calia Menethil and Derek Proudmoore have come a long way to speak with us. Let's not keep them waiting any longer.", objectives = "Meet Lilian Voss in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57377] = { id = 57377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hand Offered", description = "Here begins the calia intro" }
quests[57378] = { id = 57378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of a Shattered World", description = "The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences.\n\nSeek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings.\n\nIn the meantime, MOTHER and I shall continue our research here in the chamber. \n\nWe await your return, {name}.", progress = "Find anything of interest?", completion = "Fascinating. It appears we have our work cut out for us.", objectives = "Recover a copy of \"The Curse of Stone\" from a Horrific Vision for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57379] = { id = 57379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infested Jade Statue" }
quests[57380] = { id = 57380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sign Your Own Death Warrant", description = "Ember Ward only for bad buds!\n\n<Stonehead squints at you and shakes head.>\n\nYou not look like other bad buds!\n\nBad buds come with bad paper!", progress = "Bad buds come with bad paper!", completion = "This bad paper look very bad...", objectives = "Forge official documents condemning you to the Ember Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57381] = { id = 57381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Duelist", description = "A mortal in Revendreth. Well, well, well... you are primed to be at the head of high adventure.\n\nThe name you may call me is Nadjia the Mistblade, and, if I might be so humble as to say, I am the finest duelist that has ever wielded a sword.\n\nThis trap you found me in was a lesson learned in getting paid in advance. Release me and my blade is yours to command for as long as I find you interesting.\n\nDo we have an accord?", progress = "That consecrated iron really leaves one feeling stiff afterward.", completion = "That was FUN! I have not felt so alive in centuries. Everything about you is just... different, and invigorating.\n\nI can continue to assist you until you are ready to leave the Endmire but then we will need to part ways for a time. I have some unfinished business regarding someone who put me in a cage.", objectives = "Release Nadjia the Mistblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57384] = { id = 57384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending Monstrosity" }
quests[57386] = { id = 57386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Want Peace...", description = "Maldraxxus is a land which revels in strife and conflict. But they should also be bound by honor.\n\nIf their honor has been tossed aside, then they may move their forces beyond just Bastion.\n\nTake care, danger lies beyond that gate. It is a realm of heroes as well as a realm of villains.", completion = "Well? Why aren't you out there fighting?", objectives = "Enter Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57390] = { id = 57390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Die By the Sword", description = "What's this? You fly no colors! Where is the pride in your house, gladiator?\n\nBah, this drought has left us with slim pickings indeed, if this is the best Maldraxxus can muster!\n\nI remember the old days. The strongest souls arriving, then being divided among the five houses...\n\nNo matter. The tournament beckons. Enter the arena! Fight for glory!\n\nBy the look of you, it's likely you won't last long. Try to make a name for yourself in the time you have left.", progress = "What are you waiting for? Put on a show!", completion = "You survived? Really...\n\nI admit, that was unexpected.", objectives = "Defeat 30 contenders in the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57391] = { id = 57391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Curse of Stone\"", description = "I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth.\n\nMad ravings, intended to erode the reader's acceptance of reality.\n\nStill, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it.\n\nBring as many pages from this tome as you can find.", progress = "What have you been able to find?", completion = "Excellent work. This tome should prove quite enlightening.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57392] = { id = 57392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Curse of Stone\"", description = "Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly.\n\nThere remains much to learn, however. Continue your search for additional pages as you delve into the visions.", progress = "Urgent matters require a great deal of attention. Unless it is of the utmost importance, I must see to my work.", completion = "Fine work, indeed.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57393] = { id = 57393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stepping Through the Darkness", description = "By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. \n\nTo further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power.\n\nSeek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.", progress = "Dark and deep are the shadows.", completion = "How curious. \n\nGive me a moment. I will examine this closely.", objectives = "Recover a copy of \"Fear and Flesh\" from the depths of a Horrific Vision for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57394] = { id = 57394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"Fear and Flesh\"", description = "Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it.\n\nBut if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.", progress = "The missing pages must reside deeper within these visions. \n\nAs dark and difficult these times may seem, we mustn't forget the possibility remains of a time of great success and discovery.", completion = "Perseverance in the face of darkness.\n\nOur work continues...", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57395] = { id = 57395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", progress = "Anything to share?", completion = "I see you have found more pages from the book. Well done.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57396] = { id = 57396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"Fear and Flesh\"", description = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing.\n\nNaturally, it omits any mention of what occurs when their corruption is allowed to run unfettered.\n\nGather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", progress = "Nearly halfway there, {name}.\n\nHave you found anything new?", completion = "Magnificent. Our work is coming together nicely.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57397] = { id = 57397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", progress = "The darkness lingers.\n\nNever hurried. Never sleeping. Patiently waiting...", completion = "Ah, the final pages.\n\nI believe we're ready to advance our efforts yet again, dear {name}.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57398] = { id = 57398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking in the Darkness", description = "The end nears. The darkest corners of these visions await.\n\nOur work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.", progress = "I await your return.", completion = "Be grateful your eyes needn't stare upon these pages.\n\nWith the final pieces falling into place, we begin our preparations for Ny'alotha.", objectives = "Recover a copy of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57399] = { id = 57399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Final Truth\"", description = "I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages.\n\nEven incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting.\n\nThat being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.", progress = "I often find my own thoughts wandering, weary of what lies ahead.\n\nHow are you faring, {name}? Have you any news?", completion = "Another piece falls into place. We are so very close, {name}.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57400] = { id = 57400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Final Truth\"", description = "I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness.\n\nThis is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude.\n\nKeep looking for pages from the book, {name}. But... leave the reading to me.", progress = "Your success has brought us this far, {name}. Perhaps you have something to share?", completion = "Our journey's end approaches. The darkness gathers.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57401] = { id = 57401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Final Truth\"", description = "Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come.\n\nNo amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it.\n\nFind me the final pages of this accursed tome, {name}. I wish to learn what I need from it and be done with it forever.", progress = "The whispers of Ny'alotha surround us. I believe you are ready for the final task, are you not?", completion = "The works are complete. Together, they tell the tale of a descent into complete madness. How one deception leads to another, until reality itself is held in contempt. There is no \"truth\" to be found here.\n\nNo longer should you feel the need to run from the whispers, {name}. You are ready to silence them.", objectives = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57402] = { id = 57402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"The Curse of Stone\"", description = "N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we?\n\nThe book is nearly complete. Continue retrieving its pages from within the visions.", progress = "I believe we are on the precipice of a something grand.", completion = "A job well done, {name}.\n\nIt's time we advanced our efforts.", objectives = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57403] = { id = 57403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reconstructing \"Fear and Flesh\"", description = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair.\n\nBut you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy.\n\nContinue to collect the pages of this book. We have nearly finished piecing it back together.", progress = "Making progress?", completion = "The words in this tome build and expand on the writings from the one we completed previously.\n\nStay the course, {name}. I expect we shall have answers soon enough.", objectives = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57404] = { id = 57404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravager Hive" }
quests[57405] = { id = 57405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Madness", description = "<This wretched shamble of a venthyr mumbles uncontrollably as it claws at the ground.\n\nIt looks up suddenly and points its finger at you.>\n\nAn adversary with no ferry cannot be merry unless it is wary!\n\n<It seems to be waiting for a response from you.>", completion = "Well, aren't you an unexpected windfall?\n\nI'm afraid I've no tea to offer you at the present. Forgive my poor manners.", objectives = "Discover what Lost Sybille wants to show you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57414] = { id = 57414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mount Up Test" }
quests[57425] = { id = 57425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land of Opportunity", description = "<The grandmaster's voice rings out over the roaring crowd.>\n\nThis is it! The final event of the tournament!\n\nThese two Maldraxxi gladiators have cut down challenger after challenger. Now the only thing left...\n\nIs for one to slay the other!", completion = "In ages past, the Primus founded that tournament to showcase the might of Maldraxxus. \n\nToday, it has sparked an all-out war.", objectives = "Defeat High Champion Meskal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57426] = { id = 57426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Terrible Morning", description = "You simply won't believe what happened to me!\n\nI was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me!\n\nAmongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol.\n\nA tragedy of the highest order!\n\nWithout it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land.\n\nThe Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?", progress = "The Marquis and his ruffians must be taught some manners!", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nJustice... for parasols... everywhere...", objectives = "Kill Marquis Pummeler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57427] = { id = 57427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbearable Light", description = "Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners.\n\nThat is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body.\n\nWith the right skills, it is possible to reverse the Light's desecration if it is treated quickly.\n\nBut the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.", progress = "If only I'd been able to help them earlier...", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nMy... sincerest apologies...", objectives = "Kill 12 ash ghouls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57428] = { id = 57428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theotar's Mission", description = "Oh the Accuser sent you? How keen!\n\nI do, in fact, know the fate of Prince Renathal... at least part of it.\n\nWhen our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall.\n\nI'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think.\n\nMy parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.", progress = "My preferred colors are pink and white, if you can find it.", completion = "<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nGubbins... Where are you?", objectives = "Collect 8 Scorched Planks and 8 Regal Cloth Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57429] = { id = 57429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyre of the Amalgamated One" }
quests[57442] = { id = 57442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Desiccation", description = "<Exposure to the Light has rendered Theotar incapable of forming coherent sentences.\n\nInstead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.>\n\nLost... Syb... Tubbins... Late for tea...\n\n<You'll have to find Theotar's hideout a different way.>", completion = "<Gubbins and Tubbins speak in unison.>\n\nDis not good.", objectives = "Discover the way to Theotar's hideout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57443] = { id = 57443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Job: Demolition Detail" }
quests[57444] = { id = 57444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Inspired Moral Inventory", description = "{name}! You are well! I am glad of it.\n\nMany of the ascended who once served this place have betrayed us. To turn so wholly against all that the kyrian stand for is... unimaginable.\n\n<The acolyte places a heavy spear in your hands.>\n\nThis is a tool that has seen little use before today. Its sole purpose is to inspire a moment of reflection in those it touches. It will show them the error of their ways.\n\nIf they remain unrepentant, then there is no hope for them. They must die.", progress = "They betrayed us.", completion = "I saw them perish. It is more than they deserved.", objectives = "Slay 3 Forsworn ascended.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57445] = { id = 57445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chin's Noodle Cart" }
quests[57446] = { id = 57446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy You Know", description = "My heart is filled with dread. If it truly is Lysonia who leads them now...\n\nNo. What is important is that we restore the great vespers. So long as their mighty voices are corrupted, all who hear them will suffer as this temple does. It is only a matter of time before all of Bastion succumbs.\n\nThey will no doubt try to stop you. I will hold their leader's attention as long as I can.\n\nIf I do not survive... my disciple will see you safely from this place. Go in service.", completion = "Our fight is not yet over, {name}.", objectives = "Confront Lysonia and cleanse the great Vespers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57447] = { id = 57447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purity's Prerogative", description = "Do you feel it, {name}?\n\nThat cold hand that grips your throat? That chill settled in the pit of your stomach? That is the touch of the Maw, as certain as the Archon's will.\n\nI do not know how Lysonia came to possess this power, but we must act quickly.\n\nI will inform the Archon of what transpired here. You will act where my Hand could not. I will explain as we fly.\n\nSpeak to me when you are prepared to leave the temple.", completion = "We will see not a moment's rest today, will we?\n\n<Kleia eyes the fragment warily.>", objectives = "Fly with Vesiphone to Purity's Reflection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57448] = { id = 57448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Allies Among Us", description = "Even in times of peace, the Horde is not without its problems.   \n\nAlthough they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. \n\nWe don't turn people away when times get tough; we band together and endure. \n\nFor a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. \n\nMy only hope is that they still see as much value in the Horde as I see in them.", completion = "Vulpera within the Horde. A practical partnership, don't you agree? One that would not have been possible without your help. \n\nThanks to you, {name}, we now have a home beyond the dunes.", objectives = "Witness Baine welcome the vulpera into the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57449] = { id = 57449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executor of N'Zoth" }
quests[57453] = { id = 57453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Caller" }
quests[57454] = { id = 57454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence in the Stalks", description = "Hmm. Well that's not... great. But no cause for alarm, yet!\n\nIt has been a long time since our ring withdrew from here, and we probably need to go to its source to get it to return!\n\nUnfortunately, I haven't heard from the Chief Mushroomancer, Cortinarius, since the crisis began.\n\nPlease, find him and help us rejoin the rings! Head west of Dreamsong Fenn to the Stalks. You can't miss them... just follow the mushrooms!", completion = "Finally, a friendly face! Are you with the Hunt? You don't look like you're from around here....", objectives = "Speak to Cortinarius outside the Stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57455] = { id = 57455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushroom For Improvement", description = "The mushrooms are under attack! I need your help, or we risk losing it all!\n\nSome fae wearing strange masks came in and demanded to gain access to the rings. When I told them they were closed due to the drought, they attacked me!\n\nI'm too weak to fight back now, and I'm cut off from the center ring. These fae have destroyed so much, but there is something we can do.\n\nSprinkle some of these spores on their corpses so we can regrow the rings. Even when slain, our enemies can still serve Ardenweald.", progress = "They'd be feeding the mushrooms anyway, so you might as well accelerate the process.", completion = "Their bodies will nourish the growth and restoration of the fae rings. It is a worthy end for them.", objectives = "Use the Pouch of Spores to plant mushrooms on 15 masked fae in the Stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57456] = { id = 57456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Drinker" }
quests[57457] = { id = 57457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaking 'Shrooms", description = "The mushrooms in there need your help, {class}!\n\nSome of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there.\n\nIf you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.", objectives = "Shake 8 Swollen Mushroom Stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57458] = { id = 57458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring Repairs", description = "The damage wrought here is severe, but it can be reversed.\n\nMy master is weakened by all this destruction, but mushrooms are difficult to completely eradicate. By restoring power to the rings throughout the grove, we can strengthen them once again.\n\nTake this beacon. Use it near a damaged mushroom in a ring, and watch how quickly nature can heal its wounds.", completion = "Together we are strong.", objectives = "Use the Fungal Beacon to repair 6 Damaged Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57459] = { id = 57459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting For Fungus", description = "Behold, Marasmius!\n\nThis is his home, his heart. Every mushroom in Ardenweald, maybe even all of the Shadowlands, stems from here. And the masked fae want to take him for their own purposes. As chief mushroomancer, I cannot abide this.\n\nOur foes may look mindless, but they are clever. They will have tracked my position by now.\n\nI shall make my final stand here, and hope that Marasmius is strong enough to lend his aid.\n\nWill you stand with me, {class}?", completion = "<About time you showed up! Good thing I took care of all those young ones, eh?>", objectives = "Help Cortinarius defend Marasmius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57460] = { id = 57460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tubbins's Tea", description = "Theotar teach Tubbins special tea that make Light go away!\n\nTubbins good tea maker!\n\nWatch Tubbins make Theotar feel good!\n\nThen Tubbins feel good!", progress = "Tubbins make tea!", completion = "Tea ready! Tubbins give to Theotar!", objectives = "Help Tubbins make the special tea to heal Theotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57461] = { id = 57461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Uneventful Stroll", description = "I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening.\n\nAnyway, that tea picked me right up!\n\nWhen I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward.\n\nMyself and a few others have been working to gain access to that tower from below, but there are... obstacles.\n\nWhen you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.", completion = "<Theotar takes a slow sip from his tea cup.>\n\nWhat a delightful stroll!", objectives = "Escort Theotar to the Sanctuary of the Mad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57462] = { id = 57462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream Catcher", description = "It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further.\n\nHunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.", progress = "Fortune favors the bold, {name}. And few acts are as bold as wielding the power of an Old God.", completion = "Well done, {name}.\n\nOnce we have imbued the focus with the power we now hold, you will be able to create the most devious items of which N'Zoth's twisted mind can conceive.", objectives = "Acquire 200 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57463] = { id = 57463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Way or the Hyphae", description = "<An old, booming voice fills your mind.>\n\nHmph. More are coming.\n\nI would rather not lose more of myself, and I don't want you to think I'm not appreciative of the work you and Cort here have done.\n\nHow about you take a ride on the rings and give those oafs a good thrashing? We'll teach them not to mess with Marasmius and his fae rings!", completion = "Hah! I haven't felt that young in ages!", objectives = "Ride the fae rings with Marasmius and defeat 30 invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57464] = { id = 57464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Focus", description = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him.\n\nN'Zoth's influence is everywhere, {name}, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", progress = "We are embarking on a dangerous gambit, {name}. Caution is of the utmost importance.", completion = "Excellent. These should provide just what we need.\n\nI will draw out the corruption from these physical vessels and infuse it into the focus. Then you will be able to use it to create more powerful items.", objectives = "Acquire 20 Shred of Insanity. These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57465] = { id = 57465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Job: Wood Work" }
quests[57470] = { id = 57470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abominable Discovery", completion = "Gharmal's gluttony knew no bounds.", objectives = "Follow Draka to Gharmal's Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57471] = { id = 57471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Dirty Job", description = "This muck pool is all out of order. The anima shortage has taken its toll here for sure. \n\nYou see, the pools require filth and fiber to grow dredgers effectively. The problem is every time I try to treat the pool, the dang devourers are on my back!\n\nNow the untreated muck is starting to coagulate into these elementals! Can you go and toss some of the filthy rubble into the pool to restore it?", completion = "I can smell it from here. Thanks for that, {name}.", objectives = "Throw Filthy Rubble into the muck pool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57473] = { id = 57473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Possession", description = "This chest is different. It's larger than the others... but more importantly, it's locked.\n\n<Mograine bashes the lock apart.>\n\nNow, let's see what's inside.", progress = "How did they acquire that?", completion = "The Mantle of the Primus... \n\nFate favors us today.", objectives = "Open the ornate chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57474] = { id = 57474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dredger Duty", description = "You fixed up the muck pool so we can make some dredgers, but them devourers are gonna keep causin' trouble.\n\nWe're gonna need a Gem of Binding so we can dredge up a biggun to protect the pool.\n\nI'll show you how to dredge up some disposable dredgers to work with for now.\n\nGet 'em digging in the rubble to find us a Gem of Binding, and then we'll reshape 'em all into a biggun to kick them devourers outta here!", progress = "You got the gem?", completion = "Got a bit of devourer gunk on it, but it will have to do.", objectives = "Dredge a dredger and bring it to the pile of rubble. Wait for it to dig through the pile and collect the Gem of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57475] = { id = 57475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantle Returned", description = "The Mantle of the Primus...\n\nI can hardly believe it. That Gharmal possessed it. That they did not use it against us. That we reclaimed it.\n\nThis could prove vital toward our efforts to restore Maldraxxus. We must return it to Baroness Draka at the Seat of the Primus immediately.", completion = "I'll send scouts to continue the search, but this... this is a huge boon for us.", objectives = "Return to Draka at the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57476] = { id = 57476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vil'thik Feeding Grounds" }
quests[57477] = { id = 57477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Gonna Need a Bigger Dredger", description = "Thanks for getting the stone, {name}. While you were out I went ahead and dredged up a few more folks.\n\nNow we just need to re-shape these dredgers into a biggun.", progress = "What do you want?", completion = "Bootus ready.", objectives = "Witness the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57481] = { id = 57481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running a Muck", description = "Bootus ready to smash devourer skulls.\n\nHop on.", progress = "Enders smashed?", completion = "Nice work, {name}. \n\nBigguns can be... a bit much sometimes.", objectives = "Board Bootus and quell the devourer incursion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57484] = { id = 57484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Wakening" }
quests[57486] = { id = 57486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waning Energy", description = "Mekkatorque's pod is powering down. \n\nWe are no longer able to hear him speak. \n\nHis pulse has slowed, in spite of the best efforts of Kul Tiran healers.\n\nI have an idea, but I am going to need your help.\n\nMeet me at Proudmoore Keep. We must go soon.", completion = "What we're about to do may not be... uh... an approved plan. \n\nWe will just ask for forgiveness later.", objectives = "Meet Kelsey Steelspark at Proudmoore Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57487] = { id = 57487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Who Can Help", description = "I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... \n\nThe mechagnomes have advanced techniques in biomechanical repair and improvements.\n\nIf there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters.\n\nWill you please help me get Mekkatorque's Pod to Mechagon?", progress = "How can I help?", completion = "It would be my pleasure to give aid to the most esteemed High Tinker Mekkatorque!", objectives = "Help Kelsey move Mekkatorque's Escape Pod to Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57488] = { id = 57488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Current Schematic", description = "I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions.\n\nThere are some items I will need you to procure. \n\nFrom the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project.\n\nThe Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.", progress = "Were all assets found?", completion = "Yes, yes, these will do.\n\nExcellent work, {name}!", objectives = "Collect 4 Heat Tolerant Ooze and 6 Acquisitioned Machine Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57490] = { id = 57490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voyage to Safety", description = "One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. \n\nSince we started bringing goods in from Tiragarde, they have been a real thorn in our side. \n\nPiston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard.\n\nPlease hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open.\n\nAhem, we would not be upset if you did a little beach clean-up while you were there...", progress = "Did everyone make it back in one piece?", completion = "I hope the poor guy didn't get shaken around too much in there.", objectives = "Defeat the scavenging troggs and retrieve Mekkatorque's Escape Pod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57491] = { id = 57491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better... Stronger... Less Dead", description = "King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. \n\nThere are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning.\n\nThe logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic.\n\nThey currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.", progress = "Did you acquire the parts we need?", completion = "Barely a scratch on them!\n\nA couple of upgrades and you could do that in half the time, you know.", objectives = "Collect the Neural Accelerator, Omni Electromagnetic Amplifier, and Flux Energized Servos from the erratic units.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57492] = { id = 57492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Him?", description = "Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader.\n\nFrom what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. \n\nI seek a solution that will be most amenable to all. Will you gather the information I need?", progress = "Have your communications been productive?", completion = "Excellent, excellent, these are the results I was hoping for. You have strengthened my theory.", objectives = "Gather data from gnomes and mechagnomes in Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57493] = { id = 57493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mental Attunement", description = "We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. \n\nYour assistance is needed to get him stabilized and synchronized before removing him from his pod.\n\nPlease position yourself by the Synchroscope. I will make adjustments, you will need to fire the machine when I call.", progress = "Did you successfully push the button?", completion = "Your button pushing skills are commendable. \n\nWe are fortunate you were here.", objectives = "Activate the Synchroscope when Christy tells you to fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57494] = { id = 57494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strong Heart", description = "We saw a flare near Junkwatt Depot. \n\nThe retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose.\n\nThis is great news!\n\nHowever, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor.\n\nPlease move with haste, we are so close to completion.", progress = "Are you ready?", completion = "I am quite pleased.\n\nWith a 40% chance of success, I was not sure the variables would reconcile in our favor.\n\nIt was a serendipitous sequence of events.", objectives = "Retrieve the Spark Reactor and complete Mekkatorque's procedure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57495] = { id = 57495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Mechagon", description = "Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike.\n\nIt is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come!\n\nWhen you are ready, please join us at the High Tinkertory for a special address.", progress = "When you are ready, please join us at the High Tinkertory for a special address.", completion = "This has truly been a glorious day for both gnomes and mechagnomes! We could not have done it without you, {name}!", objectives = "Travel to the High Tinkertory in Mechagon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57496] = { id = 57496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascension", description = "After everything the mechagnomes have done for us today, it is our duty to return the favor.\n\nLet us clear out the rogue creations that remain in Mechagon. \n\nWith their home returned, Prince Erazmin and his people will have a brilliant path forward.\n\nWith this team, we will make short work of the remaining King Mechagon loyalists.\n\nLet me know when you are ready to roll out!", completion = "That was exciting! \n\nThe world just got a little bigger, my friend!", objectives = "Clear the remaining Mechagon defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57497] = { id = 57497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagate the News", description = "We wanted to save a life and we have accomplished so much more!\n\nWe really couldn't have done it without you, {name}. I am so excited about the future of all gnomekind.\n\nHead back to Stormwind and share the good news!", completion = "Outstanding results, {name}! \n\nI will share your news with the leaders of the Alliance.\n\nI look forward to collecting some new toys...", objectives = "Update Aysa Cloudsinger in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57506] = { id = 57506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Lost", description = "Some of our aspirants foolishly believed they could enter the Maw and make a difference in that dark abyss.\n\nSadly, they are mistaken. To enter the Maw is to invite eternal damnation.\n\nBut not for you.\n\nPlease investigate their fate. If you can find them, their souls might once again be free.", objectives = "Find Kyrian Aspirants within the Maw and return with their souls to Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57508] = { id = 57508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zara'thik War Banner" }
quests[57510] = { id = 57510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darklord Taraxis" }
quests[57511] = { id = 57511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms for the Poor", description = "This trench is strewn with the remnants of countless attacks upon the Seat of the Primus by forces which threatened the Shadowlands.\n\nEach time, Maldraxxus claimed victory.\n\nNow scavengers pick at scraps in hopes of buying their way into one of the three remaining houses. In these desperate times, we must gain every advantage possible over our rivals.\n\nIf we arm these scavengers and offer them a second chance at glory, we can bolster the ranks of the Chosen.", progress = "There should be plenty of weapons found on this old battlefield.", completion = "And now we test them.", objectives = "Arm 8 Displaced Scavengers with weaponry scattered around the Iron Trench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57512] = { id = 57512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk Among Death", description = "This trench echoes with necromantic energies unleashed in the countless battles waged here. That power has coalesced into chaotic entities we call deathwalkers.\n\nIn simpler times, we would have sent troops out to subdue them to serve the House of the Chosen. But with war brewing, there is no time for that.\n\nEliminate this potential threat, before our enemies turn them against us.", completion = "Everything in this land is dangerous. There is no room for weakness.", objectives = "Kill 8 Unbound Deathwalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57513] = { id = 57513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy of My Enemy", description = "I have no doubt you have questions. Know that we share enemies in this land.\n\nFor now, we must move. I will get you to a safer location and then we can speak.", objectives = "Escape from the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57514] = { id = 57514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Act of War", progress = "What are you waiting for?", completion = "Mark my words, recruit. We will crush the other houses for their acts of treason.", objectives = "Report to Baron Vyraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57515] = { id = 57515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The House of the Chosen", description = "<Draka gestures to the sky.>\n\nLook there, mortal. That is the necropolis of Margrave Krexus, who leads the House of the Chosen. It is my honor to serve as his baroness.\n\nLet us ride to our fortress. There we can gather our strength and make ready for the battle to come.", progress = "Yes?", completion = "The Chosen are all that remains of what the Primus stood for.\n\nWe are the last hope of this realm.", objectives = "Head to the House of the Chosen with Draka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57516] = { id = 57516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Fire and Flames", description = "Margrave Krexus was pleased to hear of your service to our house. He senses great potential within you.\n\nPotential that must be tested.\n\nA stone stands at the center of our citadel, surrounded by magma. Reaching the stone is a challenge of endurance and fortitude.\n\nThis trial is usually attempted only by our most renowned soldiers, but Margrave Krexus commands you to attempt the rite at once.\n\nGo on, then. Prove your worth.", progress = "What happened?", completion = "This blade was inside the stone all this time... \n\nMargrave Krexus was right about your potential.", objectives = "Reach the Standing Stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57517] = { id = 57517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Caller" }
quests[57519] = { id = 57519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Caller" }
quests[57521] = { id = 57521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered War Wagon" }
quests[57522] = { id = 57522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Void" }
quests[57524] = { id = 57524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accessing the Archives", description = "The information you've gathered has allowed us to better understand these manifestations.\n\nI believe MOTHER is waiting to share some of her findings with you.", progress = "Do you require assistance?", completion = "Archival database now available.", objectives = "Speak with MOTHER to activate the Titanic Research Archive, then examine the archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57529] = { id = 57529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garden in Turmoil", description = "Please excuse me for not standing. I would rather not disturb these creatures.\n\nIf you have a desire to help the creatures of Bastion, Zosime needs aid to regain control of our garden. You will find her just down this path.\n\nGo in service.", completion = "Oh, you're here to lend a hand? Wonderful!", objectives = "Speak with Zosime downhill in the Garden of Respite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57530] = { id = 57530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gharmal's Tower", description = "Gharmal collected anything they believed to be an item of power.\n\nWe'll need to search the tower. There is almost certainly something here of value to us.", completion = "That is definitely something. Let's open it and find out.", objectives = "Search Gharmal's Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57531] = { id = 57531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unfortunate Situation", description = "Laurent, mirror maker to the Master. Pleasure to meet you. Excuse my disheveled appearance. It appears I've found myself in a most unfortunate situation.\n\nI was attempting to travel on royal business when my mirror sent me to this wasteland instead.\n\nNot a moment after I arrived, a band of exiles ripped the clothes right from my back, making it impossible for me to traverse this unforgiving terrain.\n\nAssist me and I will endeavor to create a mirror which will allow us to escape this wretched place.", progress = "Have you recovered my belongings?", completion = "This is it? Are you sure there wasn't more?", objectives = "Defeat Costel and recover Laurent's belongings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57532] = { id = 57532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foraging for Fragments", description = "Forgive me. I don't mean to appear ungrateful, but my mirror fragments are missing.\n\nI shouldn't be surprised, really. They're quite powerful and I'm sure the miscreants out here would be happy to get their hands on them.\n\nNonetheless, I will not let this deter me.\n\nThe Master sends his stone servants to smash any mirrors erected in this ward, so we should have no trouble finding fragments nearby.", progress = "Simone shouldn't be here!", completion = "This must be some sort of mistake!", objectives = "Follow Laurent and collect Mirror Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57533] = { id = 57533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Punishment", description = "The reasons we were banished here differ, but our goal once we arrive is always the same--to avoid becoming ash.\n\nThe Shrouded control the areas shaded from Light. Those that trespass within their stronghold are made to suffer. Our flesh blisters and burns, yet we do not die. Instead, our minds descend into madness from the pain.\n\nI do not claim to know the crimes of those trapped within the Light, but I know this is not the Maw. It is not our role to punish.\n\nFree the others as you have freed me.", progress = "Penance, not punishment. It seems the Master has forgotten the difference.", completion = "You freed them, yes? Let us hope they found some small sliver of respite, where the Light cannot reach.", objectives = "Free 5 Blistering Outcasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57534] = { id = 57534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Only Ash Remains", description = "Is this really what becomes of the exiled? Are they left here to burn to ash?\n\nHow could the Master allow such a thing? It is cruel. Heartless, even.\n\nNo venthyr would want to continue on like this. \n\nYou must end their suffering.", completion = "I thought I knew our sire, but anyone who would do this to his subjects is not worth following.", objectives = "Kill 10 Ashen Ravagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57535] = { id = 57535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escaping the Master", description = "Now more than ever I wish to escape this place, but I cannot go back to serve the Master. Not after seeing what goes on here.\n\nSimone and I are in agreement. With your assistance, I will craft a mirror that connects to a sanctuary controlled by the prince. We will leave this place and pledge our support to Renathal. \n\nBut first, I'll need fragments of glass. The Shrouded seem to have plenty, and the fewer they have to make traps, the better.", progress = "Have you collected the fragments?", completion = "<Laurent carefully examines the fragments before speaking.>\n\nYes, these should work. I'm almost certain.", objectives = "Collect 10 Mirror Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57536] = { id = 57536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror Making, Not Breaking", description = "Denathrius does not allow mirrors to be erected within the ember ward. His stone servants shatter anything that so much as glints. \n\nI need you to remain vigilant as I make this mirror. I have no doubt that the Master's minions will try to stop us. \n\nAre you ready?", completion = "Simone is right. We don't have time for idle chatter. Not here, at least.\n\nThe mirror we've repaired will take you to safety.", objectives = "Defend Laurent and Simone from Stone Legion attackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57537] = { id = 57537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covering our Tracks", description = "I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there.\n\nWe'll fly the rest of the way. Approach my flayedwing when you are prepared.", objectives = "Ride with Draka to the House of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57538] = { id = 57538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing the Peace", description = "This anima drought isn't hard on just the kyrian. The wildlife of Bastion are suffering too!\n\nMany creatures are becoming aggressive and menacing, wyrms and cloudfeathers especially. They are hurting the other wildlife and long beyond saving.\n\nIf someone doesn't clear this garden of these starved creatures, we can no longer meditate here. And if we can no longer meditate, that will make the anima shortage even worse!", progress = "We must deal with the anima-starved creatures so this place can return to a state of tranquility.", completion = "We can now better fulfill our duties here. I look forward to resuming my meditations. Thank you.", objectives = "Kill 10 Anima-Starved creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57540] = { id = 57540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunchong Incubator" }
quests[57541] = { id = 57541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Void" }
quests[57542] = { id = 57542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Caller" }
quests[57543] = { id = 57543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executor of N'Zoth" }
quests[57545] = { id = 57545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distractions for Kala", description = "When the animals became aggravated, we left in a hurry. However, all of Kala's toys are still inside the garden.\n\nSince you are going to be there, would you please collect them? Kala may be very large, but she is still young. She can be a bit of a troublemaker as well.\n\nHopefully the return of her toys will help keep her distracted.", progress = "Do you have her playthings? She's becoming quite the handful!", completion = "Kala! Look! {name} brought back your favorite things!", objectives = "Collect Kala's playthings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57547] = { id = 57547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Courage", description = "I'm still new and haven't passed all of my Aspirant tests. But, I have an idea.\n\nThere is an artifact called Korinna's Allaying Crook. Korinna was a powerful Ascended who tamed the creatures of Bastion eons ago. Her staff has the power to prevent more creatures from succumbing to a savage, anima-starved state.\n\nHowever, the artifact is protected and only one with great courage can retrieve it. I bet you could, {name}.\n\nGo on ahead. The staff is in the reliquary to the north. I'll join you there shortly.", progress = "Were you able to retrieve the crook?", completion = "I told you she can be quite the troublemaker. Ugh, Kala!", objectives = "Help Zosime retrieve Korinna's Allaying Crook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57549] = { id = 57549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Agthia's Memory", description = "Greetings, mortal!\n\nAre you here to learn about the legacy of Agthia, Paragon of Courage?\n\nI welcome you to walk the grounds of this ancient battleground to learn of the battle that occurred here, and the heroic Paragon who saved all of Bastion and the Shadowlands.", progress = "Agthia did not only live a life of courage, but one of service to all of the Shadowlands.", completion = "It is an eternal tug of war between the cosmic forces of existence. \n\nThey constantly vie for power over each other but if one fell, all worlds would fall into chaos.", objectives = "Read the Scrolls of Remembrance around Agthia's Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57551] = { id = 57551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agthia's Path", description = "Now that you have familiarized yourself with the events leading to the battle that took place here eons ago, it is time to experience it for yourself.\n\nRing the bell, take a deep breath, and walk in Agthia's steps.", completion = "To arms, kyrian! We must stand strong before the forces of the Void!", objectives = "Ring the Vesper of History.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57552] = { id = 57552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warriors of the Void", description = "These Void invaders are wiping our forces from existence!\n\nMy disciples fall, returning their anima to the lands.\n\nIf we fail to drive them from our lands, more than kyrian will be lost. First Bastion, then the Shadowlands as a whole.", completion = "Wherever you step, you leave a wake of vanquished Void forces in your path.\n\nYou give your peers time to breathe.", objectives = "Kill 15 Void forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57553] = { id = 57553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Wounded Wings", description = "I see my peers fall in pain, their wounds from the Void overtaking them.\n\nWe cannot allow ourselves, or each other, to give up hope.\n\nShare your anima with our wounded brothers and sisters. Help them stand tall for another fight!", completion = "My disciples resolve, standing to fight another day.\n\nI will not take that in vain.", objectives = "Heal 5 Wounded Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57554] = { id = 57554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicked Gateways", description = "The forces of the Void are infinite.\n\nThey travel through the Great Beyond by creating portals, twisting gateways between our planes.\n\nQuickly, move to close these portals. Cripple the swell of their forces for as long as we can hold.", progress = "New portals shall open, but we can prevent the swell for a time.", completion = "Do not revel in our victory. More shall break through.\n\nWe must use this opportunity to strike.", objectives = "Destroy 3 Void Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57555] = { id = 57555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow's Fall", description = "Despite our efforts, the Void stands strong. All of the forces of Bastion fight, and fall one by one...\n\nThe Void cannot destroy us!\n\nThey are led by Tezulat the Annihilator, scourge of a thousand realms. This day, his reign of terror will end!", progress = "We shall sing the songs of Agthia, hero of Bastion, for eternities to come.", completion = "Now you have bore witness to Agthia's great sacrifice.", objectives = "Kill Tezulat the Annihilator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57558] = { id = 57558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vil'thik Hatchery" }
quests[57562] = { id = 57562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amathet Assault Tracker" }
quests[57563] = { id = 57563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Assault Tracker" }
quests[57564] = { id = 57564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantid Assault Tracker" }
quests[57565] = { id = 57565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqir Assault Tracker" }
quests[57566] = { id = 57566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "N'Zoth Assault Tracker (Uldum)" }
quests[57567] = { id = 57567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "N'Zoth Assault Tracker (Vale)" }
quests[57568] = { id = 57568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tough Love", description = "Heavens! Kala has flown off with Korinna's Allaying Crook!\n\nI saw her fly into her den to the west. I must warn you, she can become very protective when she's in there. Please be careful, but do not be afraid to give her some tough love. She is exceptionally resilient.\n\nHere, take her slobber ball. It's her favorite and may help to distract her.", progress = "Do you have the crook?", completion = "With the crook and Korinna's guidance, I can begin to bring this place and its creatures back to their former state of respite. Thank you, {name}.", objectives = "Retrieve Korinna's Allaying Crook from Kala inside her den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57571] = { id = 57571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving Mirrors", description = "What sort of horrific trap is this? The Light is being reflected directly on her! \n\nSimone's a dear friend of mine! Free her from that thing, please!", completion = "Denathrius may not have set the mirrors, but it's his fault I am here.\n\nThose that rouse his suspicion are sent here to suffer, even once loyal servants like myself.", objectives = "Redirect the mirror fragments to free Simone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57580] = { id = 57580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executor of N'Zoth" }
quests[57581] = { id = 57581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plucking Plumes", progress = "Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nContinue to bring me more feathers as proof of your victory over them.", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, yes, continue to show Skettis that we outcasts will not take their punishment lying down. I can arrange for more, should you provide me with additional feathers." }
quests[57582] = { id = 57582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executor of N'Zoth" }
quests[57583] = { id = 57583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Veil", description = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving.\n\nHere, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you?\n\nCome back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", completion = "Ahh, it's nice to stretch out again. I've missed this place, you know.\n\n<Marasmius pauses for a moment.>\n\nDon't tell anyone here I said that, all right?", objectives = "Find somewhere to plant Marasmius in the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
